/**
 * must: the new domain reproduces the frozen prototype engine on every golden fixture — parse normalization, internal
 *       score and balance per node for equal/shares/structural and per person, marginal effects, rankings, feasibility,
 *       ballot preferences, influence summaries and displayed directions (G-02…G-16, V-01…V-03)
 * test: tests/golden/golden.test.ts (fixtures generated by scripts/golden-from-proto.mjs)
 * red-against: a clamp dropped, a missing review read as 0, AI reviews pooled into the human mean, a stale fingerprint
 *              accepted, the thesis given a synthetic review, a secondary link counted at its target twice
 */
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import {
  argumentBalance,
  decisionRanking,
  decisionRankingForAssessor,
  directionFromInfluence,
  evaluate,
  evaluateAssessor,
  influenceSummary,
  marginalTargetEffects,
  optionFeasibility,
  optionPreference,
  parseProject,
  personalInfluence,
} from '../../src/domain/index.ts';
import type { NodeScore, Project, Scores } from '../../src/domain/index.ts';

const dir = path.join(process.cwd(), 'tests', 'golden');
const jsonRoundTrip = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

/** The same normalization the generator applied to the prototype's results. */
function nodeResult(r: NodeScore) {
  return {
    score: r.score,
    balance: argumentBalance(r.score),
    base: r.base,
    delta: r.delta,
    positive: r.positive,
    negative: r.negative,
    incomplete: Boolean(r.incomplete),
    votesCount: r.votesCount ?? null,
    totalPower: r.totalPower ?? null,
    contributions: r.contributions.map((c) => ({
      id: c.id,
      subjectType: c.subjectType,
      impact: c.impact,
      strength: c.strength,
      magnitude: c.magnitude,
      missing: c.missing,
      ...(c.overlapWarning !== undefined ? { overlapWarning: c.overlapWarning } : {}),
    })),
  };
}
const mapToObject = <V, R>(map: Map<string, V>, pick: (v: V) => R) =>
  Object.fromEntries([...map.entries()].map(([k, v]) => [k, pick(v)]));
const scoresToObject = (scores: Scores) => mapToObject(scores, nodeResult);

interface Fixture {
  name: string;
  source: string;
  project: Project;
  modes: Record<string, { nodes: unknown; marginal: unknown; ranking: string[] | null }>;
  assessors: Record<string, { nodes: unknown; ranking: string[] | null }>;
  options: Record<string, { feasibility: unknown; preference: unknown }>;
  influence: { primary: Record<string, unknown>; secondary: Record<string, unknown> };
  directions: Record<string, { current: boolean; influence: number | null; direction: string }>;
}

for (const file of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
  const fixture = JSON.parse(readFileSync(path.join(dir, file), 'utf8')) as Fixture;
  const name = fixture.name;

  test(`${name}: parseProject normalizes exactly as the prototype`, () => {
    assert.deepEqual(jsonRoundTrip(parseProject(fixture.project)), fixture.project);
    if (fixture.source.startsWith('witt-grace-gpt-proto/examples/')) {
      const raw = JSON.parse(readFileSync(path.join(process.cwd(), fixture.source), 'utf8')) as unknown;
      assert.deepEqual(jsonRoundTrip(parseProject(raw)), fixture.project);
    }
  });

  for (const weighting of ['equal', 'shares', 'structural'] as const) {
    test(`${name}: evaluate (${weighting}) matches every node`, () => {
      const project = parseProject(fixture.project);
      project.settings.assessmentWeighting = weighting;
      const scores = evaluate(project);
      assert.deepEqual(jsonRoundTrip(scoresToObject(scores)), fixture.modes[weighting]?.nodes);
      const marginal = mapToObject(marginalTargetEffects(project, scores), (e) => ({
        parentId: e.parentId,
        targetId: e.targetId,
        localDelta: e.localDelta,
        delta: e.delta,
        provisional: e.provisional,
      }));
      assert.deepEqual(jsonRoundTrip(marginal), fixture.modes[weighting]?.marginal);
      const ranking = project.mode === 'decision' ? decisionRanking(project, scores).map((r) => r.node.id) : null;
      assert.deepEqual(ranking, fixture.modes[weighting]?.ranking);
    });
  }

  test(`${name}: evaluateAssessor matches every person`, () => {
    const project = parseProject(fixture.project);
    for (const user of project.users) {
      const scores = evaluateAssessor(project, user.id);
      assert.deepEqual(jsonRoundTrip(scoresToObject(scores)), fixture.assessors[user.id]?.nodes, `person ${user.name}`);
      const ranking =
        project.mode === 'decision' ? decisionRankingForAssessor(project, user.id, scores).map((r) => r.node.id) : null;
      assert.deepEqual(ranking, fixture.assessors[user.id]?.ranking, `ranking for ${user.name}`);
    }
  });

  test(`${name}: feasibility, ballot preference, influence summaries and directions match`, () => {
    const project = parseProject(fixture.project);
    for (const node of project.nodes) {
      if (node.relation !== 'option') continue;
      assert.deepEqual(jsonRoundTrip(optionFeasibility(project, node.id)), fixture.options[node.id]?.feasibility);
      assert.deepEqual(jsonRoundTrip(optionPreference(project, node.id)), fixture.options[node.id]?.preference);
    }
    const primary: Record<string, unknown> = {};
    for (const node of project.nodes) {
      if (node.kind !== 'claim' || !node.parentId || node.sharedReasonId) continue;
      try {
        primary[node.id] = influenceSummary(project, 'primary', node.id);
      } catch {
        // not an assessable relation
      }
    }
    assert.deepEqual(jsonRoundTrip(primary), fixture.influence.primary);
    const secondary: Record<string, unknown> = {};
    for (const link of project.links) secondary[link.id] = influenceSummary(project, 'secondary', link.id);
    assert.deepEqual(jsonRoundTrip(secondary), fixture.influence.secondary);
    for (const node of project.nodes) {
      if (node.kind !== 'claim' || !node.parentId) continue;
      for (const user of project.users) {
        const own = personalInfluence(project, 'primary', node.id, user.id);
        const influence = own.current && own.record ? own.record.influence : null;
        assert.deepEqual(
          { current: own.current, influence, direction: directionFromInfluence(influence, node.relation) },
          fixture.directions[`${node.id}:${user.id}`]
        );
      }
    }
  });
}
